prelude_js:
// 七格火星车走廊，两个动作（←/→），0.5 动 0.5 留，r=(1,0,0,0,0,0,10)。
// 本片所有数字都由这个模型算出，未经修饰 —— 数值已用独立脚本核对过。
var RR=[1,0,0,0,0,0,10];
function rnx(s,a){var t=(a===0?s-1:s+1);return (t<0||t>6)?s:t;}
function rQ(V,s,a,g){return RR[s]+g*(0.5*V[s]+0.5*V[rnx(s,a)]);}
function rVI(g,k){var V=[0,0,0,0,0,0,0],i,s;
  for(i=0;i<k;i++){var N=[];for(s=0;s<7;s++)N.push(Math.max(rQ(V,s,0,g),rQ(V,s,1,g)));V=N;}
  return V;}
function rEval(pi,g,k){var V=[0,0,0,0,0,0,0],i,s;
  for(i=0;i<(k||3000);i++){var N=[];for(s=0;s<7;s++)N.push(rQ(V,s,pi[s],g));V=N;}
  return V;}
function rGreedy(V,g){var p=[],s;for(s=0;s<7;s++)p.push(rQ(V,s,0,g)>=rQ(V,s,1,g)?0:1);return p;}
function pstr(p){return p.map(function(a){return a===0?"←":"→";}).join("");}

